import torch
import torch.nn as nn
import torch.utils.cpp_extension as cpp

# ------------------------------------------------------------------------
# CUDA kernel source (compiled at import time)
# ------------------------------------------------------------------------
cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void mean_reduce_kernel(const __half* __restrict__ input,
                                   __half* __restrict__ output,
                                   int N,
                                   int R) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    for (int i = idx; i < N; i += stride) {
        float sum = 0.0f;
        const __half* row = input + i * R;
        #pragma unroll 8
        for (int j = 0; j < R; ++j) {
            sum += __half2float(row[j]);
        }
        output[i] = __float2half(sum / R);
    }
}

void mean_reduce_cuda(at::Tensor input, int /*dim*/, at::Tensor output) {
    // input is assumed to be contiguous and have the reduction dimension as the last one
    const int R = input.size(-1);
    const int N = input.numel() / R;

    const int threads = 256;
    const int blocks = (N + threads - 1) / threads;

    mean_reduce_kernel<<<blocks, threads>>>(
        reinterpret_cast<const __half*>(input.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(output.data_ptr<at::Half>()),
        N,
        R
    );

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA kernel launch error: %s\\n", cudaGetErrorString(err));
    }
}
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("mean_reduce_cuda", &mean_reduce_cuda, "Mean reduction CUDA kernel");
}
'''

# Compile the inline extension
_mean_reduce = cpp.load_inline(
    name='mean_reduce_inline',
    cpp_sources='',
    cuda_sources=cuda_source,
    functions=['mean_reduce_cuda'],
    verbose=False,
)

# ------------------------------------------------------------------------
# Model that uses the custom kernel
# ------------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model that computes mean reduction
    using a custom CUDA kernel. All tensors are fp16.
    """
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure contiguous input
        x = x.contiguous()
        dim = self.dim

        # Move the reduction dimension to the innermost position
        perm = list(range(x.dim()))
        perm.append(perm.pop(dim))
        x_perm = x.permute(perm).contiguous()

        # Allocate output (reduction dimension removed)
        out_shape = x_perm.shape[:-1]                     # everything except last dim
        out = torch.empty(out_shape, dtype=torch.float16, device=x.device)

        # Launch kernel (the kernel expects the last dimension to be the reduction axis)
        _mean_reduce.mean_reduce_cuda(x_perm, dim, out)

        # Inverse permutation to restore original ordering (without the reduced dim)
        inv_perm = [perm.index(i) for i in range(x.dim()) if i != dim]
        out = out.permute(inv_perm)

        return out

# ------------------------------------------------------------------------
# Helper functions matching the reference API
# ------------------------------------------------------------------------
def get_inputs():
    batch_size = 128
    dim1 = 4096
    dim2 = 4095
    x = torch.rand(batch_size, dim1, dim2, dtype=torch.float16, device='cuda')
    return [x]

def get_init_inputs():
    # dim = 1 in the reference example
    return [1]
